css:
.mp-report { font-size: 11px; color: #222; }
.mp-page { page-break-after: always; padding-bottom: 8px; }
.mp-page:last-child { page-break-after: auto; }
.mp-report h1 { font-size: 30px; margin: 120px 0 8px; text-align: center; }
.mp-report h2 { font-size: 20px; text-align: center; margin: 0 0 40px; font-weight: normal; }
.mp-report h3 { font-size: 14px; margin: 18px 0 8px; }
.mp-report h4 { font-size: 12px; margin: 14px 0 6px; }
.mp-tag { text-align: right; font-size: 10px; color: #666; }
.mp-center { text-align: center; }
.mp-strong { font-weight: 600; }
.mp-light { font-weight: normal; }
.mp-note { margin: 14px 0 6px; }
.mp-meta { margin: 0 auto; }
.mp-meta td { padding: 4px 14px; }
.mp-meta td:first-child { font-weight: 600; text-align: right; }
.mp-grid { border-collapse: collapse; width: 100%; margin: 6px 0; }
.mp-grid th, .mp-grid td { border: 1px solid #777; padding: 3px 6px; vertical-align: middle; }
.mp-grid th { background: #d9d9d9; text-align: center; }
.mp-narrow { width: 70%; margin-left: auto; margin-right: auto; }
.mp-summary { width: 100%; }
.mp-summary > tbody > tr > td { vertical-align: middle; width: 50%; }
.mp-pie { text-align: center; }
.mp-sheet-head td { background: #d9d9d9; font-size: 12px; padding: 5px 8px; }
.mp-sheet-head .mp-tol { width: 120px; text-align: center; }
.mp-band { background: #d9d9d9; text-align: center; padding: 3px; margin: 10px 0 0; border: 1px solid #777; }
.mp-two { width: 100%; }
.mp-two > tbody > tr > td { vertical-align: top; }
.mp-images { width: 52%; padding: 6px 8px 0 0; }
.mp-images figure { margin: 0 0 8px; }
.mp-images img { max-width: 100%; max-height: 230px; }
.mp-images figcaption { font-size: 9px; color: #666; }
.mp-readings { width: 48%; padding-top: 6px; }
.mp-pill { display: inline-block; padding: 2px 16px; border-radius: 4px; border: 1px solid #555; }
.mp-actions th { width: 22%; text-align: left; background: #f2f2f2; }
